pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory _tos, uint256[] memory v) public {
        // Restrict to admissible domain: msg.sender must be the required address
        vm.startPrank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        // Bound lengths to avoid excessive gas/loops, but keep it wide
        vm.assume(_tos.length == v.length);
        vm.assume(_tos.length > 0 && _tos.length <= 10);
        // Ensure the external call succeeds by skipping addresses that could cause reverts in the low-level call
        // The low-level call targets caddress with transferFrom; we need a contract at caddress that doesn't revert.
        // Since the fuzzer provides an address with no code, low-level calls to EOA always succeed.
        // So we deploy a helper that always returns true for transferFrom, to simulate a successful call.
        // Actually, the call is to caddress, which is a hardcoded address. The fuzzer cannot change it.
        // The only external party is caddress, which is fixed. A low-level call to an EOA with no code succeeds.
        // So the call will succeed if caddress has no code (which it likely doesn't, being a random address).
        // We don't need an adversarial helper because the bug is about return value, not about failing calls.
        // The reference C returns true when all internal calls succeed, M returns false.
        // We must ensure the internal calls do not revert. They revert if !_s.
        // Since caddress is a hardcoded address with no code, the low-level call returns success.
        // So the domain is naturally admissible.
        // Still, we can bound v[i] to prevent overflow: v[i] * 1e18 should not overflow.
        for(uint i = 0; i < v.length; i++) {
            vm.assume(v[i] <= type(uint256).max / 1e18);
        }
        bool result = c.transfer(_tos, v);
        vm.stopPrank();
        // The property: transfer must return true (it never reverts under these conditions)
        assertTrue(result);
    }
}

