pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    MockToken token;

    function setUp() public {
        c = new C();
        token = new MockToken();
        // Make the mock token the caddress so c calls it
        vm.store(address(c), bytes32(uint256(1)), bytes32(uint256(uint160(address(token)))));
    }

    function testFuzz_property(address[] calldata _tos, uint256[] calldata v) public {
        // Admissible domain: same length, non-empty, amounts fit in uint (implicit)
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);

        // Reset token tracking state before each call
        token.reset();

        // The transfer function checks msg.sender == 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        bool ok = c.transfer(_tos, v);

        // If the call succeeded, the total sent by the contract must match sum(v) * 1e18
        if (ok) {
            uint256 totalSent = token.totalSent();
            uint256 sumV = 0;
            for (uint256 i = 0; i < v.length; i++) {
                sumV += v[i];
            }
            // Reference: multiplies by 10^18, bug: multiplies by 1
            assertEq(totalSent, sumV * 1e18);
        }
    }
}

contract MockToken {
    uint256 public totalSent;

    function reset() external {
        totalSent = 0;
    }

    function transferFrom(address, address, uint256 amount) external returns (bool) {
        totalSent += amount;
        return true;
    }
}

