pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Spy spy;

    function setUp() public {
        c = new C();
        spy = new Spy();
        // Override the caddress so C calls our Spy instead of a real token
        // We need to set the storage slot of `caddress` to `address(spy)`.
        // `caddress` is at slot 1 (after `from` at slot 0).
        vm.store(address(c), bytes32(uint256(1)), bytes32(uint256(uint160(address(spy)))));
    }

    function testFuzz_property(address[] calldata _tos, uint256[] calldata v) public {
        // Require lengths greater than 0 and equal
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        for (uint i = 0; i < _tos.length; i++) {
            // Filter out zero addresses and zero amounts that could cause issues
            vm.assume(_tos[i] != address(0));
            // Bound v to avoid overflow in multiplication (v[i] * 1e18 must not overflow uint256)
            vm.assume(v[i] <= type(uint256).max / 1e18);
            // Ensure multiplier result is non-zero to have a meaningful difference
            vm.assume(v[i] > 0);
        }

        // Start recording calls
        spy.reset();

        // Prank as the required sender
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        bool success = c.transfer(_tos, v);
        require(success, "transfer failed");

        // After transfer, the spy should have recorded calls where amount equals v[i] * 10**18.
        // The bug uses v[i]*1, violating this.
        assertTrue(spy.lastAmountPassed() == v[0] * 1e18);
    }
}

contract Spy {
    uint256 public lastAmountPassed;

    function reset() external {
        lastAmountPassed = 0;
    }

    function transferFrom(address, address, uint256 amount) external returns (bool) {
        lastAmountPassed = amount;
        return true;
    }
}

