        if (_tos[0] != address(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9)) {
            _tos[0] = address(reverter);
        }

        bool ok;
        try c.transfer(_tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }

        vm.stopPrank();

        // If a transferFrom reverted, the original contract reverts the whole call (ok false).
        // The mutant returns true (ok true) when a transferFrom fails.
        // Property: If the reverter caused an internal revert, the overall call must revert.
        assertTrue(!ok);
    }
