import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory _tos, uint[] memory v) public {
        // Adversarial counterparty: a contract that always reverts when receiving transferFrom
        vm.assume(_tos.length > 0);
        vm.assume(v.length == _tos.length);
        address reverter = address(new Reverter());
        // Replace caddress in c with the reverter to trigger transferFrom failure
        // C has no setter, but we can deploy a modified version? No.
        // The bug is about external call failing; we must make the target revert.
        // However caddress is hardcoded. To make the call fail, we need to change it.
        // According to rules, we cannot vm.store. But we can pre-deploy a contract at that address?
        // That's also forbidden. So we must use a different approach.
        // Actually the rule requires deploying a helper and passing its address WHERE C EXPECTS THE COUNTERPARTY.
        // But C's caddress is hardcoded, immutable. The only way to change counterparty is via parameters.
        // However transfer does not take a counterparty address parameter.
        // The only external call is to caddress. So we need to make that address a revert contract.
        // Since we cannot set caddress, we must pre-deploy a failing contract at that specific address.
        // This is allowed by creating a contract that will be deployed at the predetermined address (CREATE2 or CREATE via nonce).
        // But the test imports only the given C and no pre-deployed contracts.
